import assert from "node:assert/strict";
import { readdir } from "node:fs/promises";
import path from "node:path";
import test from "node:test";
import { fileURLToPath } from "node:url";
import { isMetadataImagePath } from "../lib/intl/paths";

const localeRoot = fileURLToPath(new URL("../app/[locale]", import.meta.url));

/**
 * Metadata image routes generated by code (`apple-icon.tsx`, `icon.tsx`, `opengraph-image.tsx`,
 * `twitter-image.tsx`) have no file extension in their URL, so middleware sees them, and Next writes the
 * locale into that URL (`/zh-TW/sellers/9/apple-icon-v673w8`). `isMetadataImagePath` lets exactly the
 * listed ones through under the default-locale prefix. A new one is not served until it is listed there.
 */
const GENERATED_IMAGE_ROUTE =
	/^(?:apple-icon|icon|opengraph-image|twitter-image)\.(?:tsx?|jsx?)$/;

async function generatedImageRoutes(dir: string, base = ""): Promise<string[]> {
	const out: string[] = [];
	for (const entry of await readdir(path.join(dir, base), {
		withFileTypes: true,
	})) {
		const relative = base ? `${base}/${entry.name}` : entry.name;
		if (entry.isDirectory()) {
			out.push(...(await generatedImageRoutes(dir, relative)));
		} else if (GENERATED_IMAGE_ROUTE.test(entry.name)) {
			out.push(relative);
		}
	}
	return out.sort();
}

test("the code-generated metadata image routes under app/[locale] are the ones isMetadataImagePath knows about", async () => {
	assert.deepEqual(
		await generatedImageRoutes(localeRoot),
		["(public)/sellers/[id]/apple-icon.tsx"],
		"app/[locale] 底下的 metadata 圖片 route 變了：把新的網址型式加進 lib/intl/paths.ts 的 METADATA_IMAGE_PATHS，再更新這份清單。",
	);
	assert.equal(isMetadataImagePath("/sellers/9/apple-icon-v673w8"), true);
});
